"use client"

import { useDeleteDoctors, useGetDoctors, usePostDoctors, usePutDoctors } from "@/src/lib/ReactQuery/query/admin/doctors/query";
import { zodResolver } from "@hookform/resolvers/zod";
import { useForm } from "react-hook-form";
import z from "zod"
import Modal from "../../components/ui/Modal/Modal";
import { useState } from "react";
import { TDoctors } from "@/src/types";

const doctorsSchema = z.object({
    name: z.string().min(1, "Имя обязательно"),
    specialization: z.string().min(1, "Специализация обязательна"),
    experienceYears: z.string(),
    education: z.string(),
    certificates: z.string(),
    bio: z.string(),
    photoUrl: z.string(),
    isActive: z.string()
})
type TdoctorsSchema = z.infer<typeof doctorsSchema>;

const doctorsUpdateSchema = z.object({
    id: z.string(),
    name: z.string().min(1, "Имя обязательно"),
    specialization: z.string().min(1, "Специализация обязательна"),
    experienceYears: z.string(),
    education: z.string(),
    certificates: z.string(),
    bio: z.string(),
    photoUrl: z.string(),
    isActive: z.string()
})
type TdoctorsUpdateSchema = z.infer<typeof doctorsUpdateSchema>;

export default function DoctorsPage() {
    const [isOpenPost,setIsOpenPost] = useState<boolean>(false);
    const [isOpenPut,setIsOpenPut] = useState<boolean>(false);
    const createDoctors = usePostDoctors();
    const getDoctors = useGetDoctors();
    const putDoctors = usePutDoctors();
    const deleteDoctors = useDeleteDoctors();
    const { register: registerPut, reset: resetPut, handleSubmit: handleSubmitPut, formState: { errors: errorsPut } } = useForm<TdoctorsUpdateSchema>({
        resolver: zodResolver(doctorsUpdateSchema),
        defaultValues: {
            id: "",
            name: "",
            specialization: "",
            experienceYears: "",
            education: "",
            certificates: "",
            bio: "",
            photoUrl: "",
            isActive: "true"
        }
    })
    async function onSubmitPut(data: TdoctorsUpdateSchema) {
        putDoctors.mutate(data, {
            onSuccess: () => {
                resetPut();
                setIsOpenPut(false);
            }
        })
    }

    const { register, reset, handleSubmit, formState: { errors } } = useForm<TdoctorsSchema>({
        resolver: zodResolver(doctorsSchema),
        defaultValues: {
            name: "",
            specialization: "",
            experienceYears: "",
            education: "",
            certificates: "",
            bio: "",
            photoUrl: "",
            isActive: "true"
        }
    })
    async function onSubmit(data: TdoctorsSchema) {
        createDoctors.mutate(data, {
            onSuccess: () => {
                reset();
                setIsOpenPost(false);
            }
        })
    }

    return<main>
        <h3>Управление докторами</h3>
        <section>
        <button onClick={()=> setIsOpenPost(true)}>Создать</button>

        {getDoctors.isLoading && <p>Загрузка докторов...</p>}
        {getDoctors.isError && <p style={{ color: 'red' }}>Ошибка: {getDoctors.error?.message}</p>}
        {getDoctors.data && getDoctors.data.length === 0 && <p>Врачей пока нет</p>}

        <table>
            <thead>
                <tr>
                    <th>Имя</th>
                    <th>Cтаж(лет)</th>
                </tr>
            </thead>
            <tbody>
                {getDoctors.data?.map((doctor : TDoctors) => {

                return(<tr key={doctor.id }>
                    <td>{doctor.name}</td>  
                    <td>{doctor.experienceYears}</td>
                    <td>
                        <button onClick={() => {
                            resetPut({
                                id: String(doctor.id),
                                name: doctor.name,
                                specialization: doctor.specialization,
                                experienceYears: String(doctor.experienceYears ?? ""),
                                certificates: Array.isArray(doctor.certificates) ? doctor.certificates.join(", ") : (doctor.certificates ?? ""),
                                education: (doctor.education as { text?: string } | null)?.text || "",
                                bio: doctor.bio ?? "",
                                photoUrl: doctor.photoUrl ?? "",
                                isActive: String(doctor.isActive)
                            });
                            setIsOpenPut(true);
                        }}>Редактировать</button>
                        <button onClick={()=>{
                            const conf = confirm("Удалить?");
                            if(conf) deleteDoctors.mutate({ id: String(doctor.id) })
                            else return
                        }}>Удалить</button>
                    </td>
                </tr>)
                })}
            </tbody>
        </table>
        </section>
        <Modal isOpen={isOpenPost} onClose={()=> setIsOpenPost(false)}>
            <h3>Создание доктора</h3>
            <form onSubmit={handleSubmit(onSubmit)}>
                <label htmlFor="name">Имя</label>
                <input type="text" {...register("name")} id="name" />
                <label htmlFor="specialization">Специализация</label>
                <input type="text" {...register("specialization")} id="specialization" />
                <label htmlFor="experienceYears">Стаж</label>
                <input type="number" {...register("experienceYears")} id="experienceYears" />
                <label htmlFor="education">education</label>
                <input type="text" {...register("education")} id="education" />
                <label htmlFor="certificates">certificates</label>
                <textarea {...register("certificates")} id="certificates"></textarea>
                <label htmlFor="bio">bio</label>
                <textarea {...register("bio")} id="bio" rows={3}></textarea>
                <label htmlFor="photoUrl">photoUrl</label>
                <input type="text" {...register("photoUrl")} id="photoUrl" />
                <label htmlFor="isActive">isActive</label>
                <select {...register("isActive")} id="isActive">
                    <option value="true">Да</option>
                    <option value="false">Нет</option>
                </select>
                <button type="submit">Создать</button>
            </form>
            <button type="button" onClick={() => setIsOpenPost(false)}>Закрыть</button>
        </Modal>
        <Modal isOpen={isOpenPut} onClose={()=> setIsOpenPut(false)}>
            <h3>Обновление доктора</h3>
            <form onSubmit={handleSubmitPut(onSubmitPut)}>
                <input type="hidden" {...registerPut("id")} />
                <label htmlFor="namePut">Имя</label>
                <input type="text" {...registerPut("name")} id="namePut" />
                <label htmlFor="specializationPut">Специализация</label>
                <input type="text" {...registerPut("specialization")} id="specializationPut" />
                <label htmlFor="experienceYearsPut">Стаж</label>
                <input type="number" {...registerPut("experienceYears")} id="experienceYearsPut" />
                <label htmlFor="educationPut">education</label>
                <input type="text" {...registerPut("education")} id="educationPut" />
                <label htmlFor="certificatesPut">certificates</label>
                <textarea {...registerPut("certificates")} id="certificatesPut"></textarea>
                <label htmlFor="bioPut">bio</label>
                <textarea {...registerPut("bio")} id="bioPut" rows={3}></textarea>
                <label htmlFor="photoUrlPut">photoUrl</label>
                <input type="text" {...registerPut("photoUrl")} id="photoUrlPut" />
                <label htmlFor="isActivePut">isActive</label>
                <select {...registerPut("isActive")} id="isActivePut">
                    <option value="true">Да</option>
                    <option value="false">Нет</option>
                </select>
                <button type="submit">Обновить</button>
            </form>
            <button type="button" onClick={() => { setIsOpenPut(false) }}>Закрыть</button>
        </Modal>
    </main>
}